#!/bin/bash
# Uninstall script for Transcribe!
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Transcribe!..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Transcribe! if running..."
pkill -f "Transcribe!" 2>/dev/null || true

# Kill application with bundle ID com.seventhstring.transcribe if running
echo "Stopping application with bundle ID com.seventhstring.transcribe if running..."
killall -9 "com.seventhstring.transcribe" 2>/dev/null || true

# Remove /Applications/Transcribe!.app
echo "Removing /Applications/Transcribe!.app..."
if [ -d "/Applications/Transcribe!.app" ]; then
    rm -rf "/Applications/Transcribe!.app" 2>/dev/null || true
elif [ -f "/Applications/Transcribe!.app" ]; then
    rm -f "/Applications/Transcribe!.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.seventhstring.transcribe.plist
echo "Removing $HOME/Library/Preferences/com.seventhstring.transcribe.plist..."
if [ -d "$HOME/Library/Preferences/com.seventhstring.transcribe.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.seventhstring.transcribe.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.seventhstring.transcribe.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.seventhstring.transcribe.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/Transcribe!9 Preferences
echo "Removing $HOME/Library/Preferences/Transcribe!9 Preferences..."
if [ -d "$HOME/Library/Preferences/Transcribe!9 Preferences" ]; then
    rm -rf "$HOME/Library/Preferences/Transcribe!9 Preferences" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/Transcribe!9 Preferences" ]; then
    rm -f "$HOME/Library/Preferences/Transcribe!9 Preferences" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
